+function validateProvenanceAndFields(value, diagnostics) {
+  const failures = [];
+  if (!value || typeof value !== 'object') {
+    failures.push('value_missing');
+    return { status: 'fail', failures };
+  }
+  const hasProvenance = typeof value.provenance === 'object' && value.provenance !== null;
+  const hasEvidence = typeof value.evidence_bundle === 'object' && value.evidence_bundle !== null;
+  if (!hasProvenance) failures.push('provenance_required');
+  if (!hasEvidence) failures.push('evidence_bundle_required');
+  if (!Array.isArray(value.source_artifact_refs) || value.source_artifact_refs.length === 0) {
+    failures.push('source_artifact_refs_required');
+  }
+  if (!value.status || !Array.from(new Set([...INSTANCE_STATUSES, ...PROHIBITED_STATUSES])).includes(value.status)) {
+    failures.push('status_unknown');
+  }
+  if (PROHIBITED_STATUSES.includes(value.status)) {
+    failures.push('prohibited_accepted_status');
+  }
+  if (!RISK_TIERS.includes(value.risk_tier)) {
+    failures.push('risk_tier_unknown');
+  }
+  if (!value.review_state || typeof value.review_state !== 'string') {
+    failures.push('review_state_missing');
+  }
+  return {
+    status: failures.length === 0 ? 'pass' : 'fail',
+    failures,
+    diagnostics,
+  };
+}
+
+function unique(sortedValues) {
+  return [...new Set(sortedValues)];
+}
+
+function buildBoundaryCheckResults({
+  procedureInstances,
+  procedureStepInstances,
