+      procedureStatusCheck.failures.push(
+        ...instanceFailures.failures.map((failure) => ({
+          scope: instance.procedure_instance_id,
+          scope_type: 'procedure_instance',
+          code: failure,
+        })),
+      );
+    }
+    if (PROHIBITED_STATUSES.includes(instance.status)) {
+      procedureStatusCheck.failures.push({
+        scope: instance.procedure_instance_id,
+        scope_type: 'procedure_instance',
+        code: 'no_accepted_status',
+      });
+    }
+    if (!instance.step_span || !instance.step_span.start_step_id || !instance.step_span.end_step_id) {
+      procedureStatusCheck.failures.push({
+        scope: instance.procedure_instance_id,
+        scope_type: 'procedure_instance',
+        code: 'missing_step_endpoints',
+      });
+    }
+  }
+  for (const step of procedureStepInstances) {
+    const stepFailures = validateProvenanceAndFields(step, diagnostics);
+    if (stepFailures.status === 'fail') {
+      procedureStatusCheck.failures.push(
+        ...stepFailures.failures.map((failure) => ({
+          scope: step.procedure_step_instance_id,
+          scope_type: 'procedure_step_instance',
+          code: failure,
+        })),
+      );
+    }
+    if (step.derived_from_mark_label) {
+      procedureStatusCheck.failures.push({
+        scope: step.procedure_step_instance_id,
+        scope_type: 'procedure_step_instance',
+        code: 'mark_label_used_as_semantic_step',
+      });
+    }
+    if (!Array.isArray(step.evidence_bundle?.mark_evidence_refs)) {
+      procedureStatusCheck.failures.push({
+        scope: step.procedure_step_instance_id,
+        scope_type: 'procedure_step_instance',
+        code: 'mark_evidence_refs_required',
+      });
+    }
+  }
+
+  checks.push({
+    id: 'provenance_check',
+    status: procedureStatusCheck.failures.length === 0 ? 'pass' : 'fail',
+    failures: procedureStatusCheck.failures,
+  });
+
+  const branchGroupFailures = [];
+  const byPart = new Map();
+  for (const instance of procedureInstances) {
+    const key = `${instance.question_row_id}:${instance.question_part_id}`;
+    if (!byPart.has(key)) {
