+    }
+  }
+  checks.push({
+    id: 'endpoint_step_contract',
+    status: requiredEdgeContract.length === 0 ? 'pass' : 'fail',
+    failures: requiredEdgeContract,
+  });
+
+  const markBoundaryFailures = [];
+  for (const step of procedureStepInstances) {
+    if (Object.prototype.hasOwnProperty.call(step, 'mark_label')) {
+      markBoundaryFailures.push({
+        scope: step.procedure_step_instance_id,
+        code: 'mark_label_defined_as_field',
+      });
+    }
+  }
+  checks.push({
+    id: 'mark_labels_only_in_evidence',
+    status: markBoundaryFailures.length === 0 ? 'pass' : 'fail',
+    failures: markBoundaryFailures,
+  });
+
+  const inputChecks = {
+    id: 'input_artifacts_loaded',
+    status: inputDiagnostics.length === 0 ? 'pass' : 'warn',
+    diagnostic_count: inputDiagnostics.length,
+    diagnostics: inputDiagnostics,
+  };
+  checks.push(inputChecks);
+
+  for (const check of checks) {
+    if (check.status === 'fail') {
+      failCount += 1;
+    }
+  }
+
+  return {
+    checks,
+    validation_status: failCount === 0 ? 'pass' : 'fail',
+    failed_check_count: failCount,
+  };
