+  for (const item of procedureInstances) {
+    const key = `${item.question_row_id}:${item.question_part_id}`;
+    const existing = byQuestionPart.get(key) ?? [];
+    existing.push(item.branch_key);
+    byQuestionPart.set(key, existing);
+  }
