+    procedure_instance_count: procedureInstances.length,
+    procedure_step_instance_count: procedureStepInstances.length,
+    review_task_count: reviewTasks.length,
+    ambiguous_case_count: reviewTasks.filter((task) => task.review_state === 'unresolved').length,
